#include <vector>
#include <iostream>

void process(const std::vector<int>& v) {
    // Idiomatic and potentially faster check
    if (v.empty()) { 
        std::cout << "Container is empty.\n";
    } else {
        // ... process elements
    }

    // Avoid: Less clear and historically less performant
    // if (v.size() == 0) { /* ... */ }
}

int main() {
    std::vector<int> data;
    process(data);
}
